import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        total_len = 2 * N
        count0 = S.count('0')
        count1 = total_len - count0

        if count0 == 0 or count1 == 0:
            results.append("-1")
            continue

        if count0 % 2 != 0 or count1 % 2 != 0:
            results.append("-1")
            continue

        p_indices = []
        q_indices = []

        zeros_needed = count0 // 2
        ones_needed = count1 // 2

        current_zeros_p = 0
        current_ones_p = 0

        for idx, char in enumerate(S):
            if char == '0':
                if current_zeros_p < zeros_needed:
                    p_indices.append(idx + 1)
                    current_zeros_p += 1
                else:
                    q_indices.append(idx + 1)
            else:
                if current_ones_p < ones_needed:
                    p_indices.append(idx + 1)
                    current_ones_p += 1
                else:
                    q_indices.append(idx +1)

        if len(p_indices) != N or len(q_indices) != N:
            results.append("-1")
            continue

        p_str = "".join(S[i-1] for i in p_indices)
        q_str = "".join(S[i-1] for i in q_indices)

        if p_str == q_str:
            if count0 > 0 and count1 > 0:
                zero_indices = [i+1 for i, c in enumerate(S) if c == '0']
                one_indices = [i+1 for i, c in enumerate(S) if i > 0 and S[i-1] == '1']

                if len(zero_indices) >= 1 and len(one_indices) >= 1:
                    first_zero_idx = zero_indices[0]
                    last_one_idx = one_indices[-1]

                    if first_zero_idx in p_indices and last_one_idx in q_indices:
                        p_indices.remove(first_zero_idx)
                        p_indices.append(last_one_idx)
                        q_indices.remove(last_one_idx)
                        q_indices.append(first_zero_idx)
                        p_indices.sort()
                        p_str = "".join(S[i-1] for i in p_indices if i in p_indices)
                        q_str = "".join(S[i-1] for i in q_indices if i in q_indices)

                    if p_str == q_str:
                        if len(zero_indices) >= 2:
                            z1 = zero_indices[0]
                            z2 = zero_indices[1]
                            o1 = one_indices[0]

                            if z1 in p_indices and o1 in q_indices:
                                p_indices.remove(z1)
                                p_indices.append(o1)
                                q_indices.remove(o1)
                                q_indices.append(z1)
                                p_indices.sort()
                                p_str = "".join(S[i-1] for i in p_indices[:])
                                q_str = "".join(S[i-1] for i in q_indices[:])

                        if p_str == q_str:
                            results.append("-1")
                            continue

                    results.append(" ".join(map(str, p_indices)))
                else:
                    results.append("-1")
            else:
                results.append("-1")
        else:
            results.append(" ".join(map(str, p_indices)))

    print("\n".join(results))

